-- BigNoteBox Localization -- German (deDE)
-- Loads after enUS.lua and only on deDE clients (or with German forced in
-- Settings). Writes go through the BigNoteBox.L proxy that enUS.lua creates, so
-- any key not set here falls back to English, and the debug pseudo-locale still
-- applies. Built from a translator's files in enUS.lua's order (ALL-648,
-- 2026-11-02); comments are enUS.lua's.

if BigNoteBox.GetActiveLanguage() ~= "deDE" then return end

