L["SW_MODULES_LATER"]      = "Du kannst das alles später unter Einstellungen > Module ändern."
L["SW_MOD_TASKS_TIP"]      = "Checklisten in einer Notiz, mit Unteraufgaben. Aufgaben können sich bei der täglichen oder wöchentlichen Zurücksetzung selbst zurücksetzen, für Tages- und Wochenaufgaben."
L["SW_MOD_ALARMS_TIP"]     = "Stelle für eine Notiz einen Alarm zu einer realen oder einer Spielzeit oder zur täglichen bzw. wöchentlichen Zurücksetzung. Wenn er klingelt, erscheint die Notiz mit einem Ton, und du kannst ihn später erinnern lassen."
L["SW_MOD_SIDEBAR_TIP"]    = "Registerkarten für jeden deiner Charaktere neben der Notizliste, damit du immer die Notizen eines Charakters siehst."
L["SW_MOD_CONTEXT_TIP"]    = "Notizen lassen sich an eine Zone, eine Instanz, einen Spieler oder einen NPC binden. Wenn du dort ankommst oder sie ins Ziel nimmst, zeigt ein Hinweis die Notiz."
L["SW_MOD_FOCUS_TIP"]      = "Schreibe im Vollbild mit ausgeblendeter Spieloberfläche, für lange Notizen ohne Ablenkung."
L["SW_MOD_HISTORY_TIP"]    = "Behält frühere Versionen jeder Notiz, gespeichert beim Ausloggen oder Neuladen, damit du sie vergleichen und eine alte zurückholen kannst."
L["SW_MOD_ORACLE_TIP"]     = "Eine Suchleiste, die du mit einer Taste (Strg+Leertaste) öffnest und die jede Notiz über Titel, Text oder Tags findet, von überall im Spiel aus."
L["SW_MOD_UNIT_TIP"]       = "Erstelle eine Notiz über einen Spieler aus dem Betrachtungsfenster oder seinem Rechtsklickmenü oder über einen NPC, den du ins Ziel nimmst, mit Ausrüstung, Porträt und Details bereits eingetragen."
L["SW_MOD_QN_TIP"]         = "Fügt Quest-, Dialog- und Buchfenstern eine Notiz-Schaltfläche hinzu, damit du mit einem Klick festhalten kannst, was dort steht."
L["SW_MOD_REFBOX_TIP"]     = "Ein Fenster neben dem Editor für die Gegenstände, Zauber und Links, die du an eine Notiz anhängst, mit einer Modellansicht für Ausrüstung."
L["SW_MOD_RICH_TIP"]       = "Notizen mit Überschriften, Farben, Bildern und Links, mit einer Live-Vorschau neben dem Editor. Ausgeschaltet ist jede Notiz reiner Text."
L["SW_MOD_STICKY_TIP"]     = "Hefte eine Notiz als kleines Fenster an deinen Bildschirm, das beim Spielen sichtbar bleibt."
L["SW_MOD_TRASH_TIP"]      = "Gelöschte Notizen bleiben eine Zeit lang im Papierkorb, damit du sie zurückholen kannst. Ausgeschaltet ist das Löschen einer Notiz endgültig."
L["SW_MOD_FOLDERS_TIP"]    = "Lege Notizen in der Notizliste in eigene Ordner, und sieh sie in der Ordneransicht gruppiert."
L["SW_MOD_EXPLORER_TIP"]   = "Sieh deine Notizen als Raster aus Symbolen, das das Hauptfenster füllt, wie in einem Datei-Explorer, mit einer Werkzeugleiste zum Auswählen und Verschieben."
L["SW_MOD_TLDR_TIP"]       = "Gib einer Notiz eine kurze Zeile, ein \"zu lang; nicht gelesen\" wie \"KOS\". Sie erscheint über dem Notiztitel, im Tooltip beim Überfahren des Spielers oder NPCs, um den es geht, und im Hinweis der Notiz."
L["SW_MOD_TOASTS_TIP"]     ="Kleine Einblendungen auf deinem Bildschirm, wenn die Situation einer Notiz oder einer Aufgabe passt. Ausgeschaltet erscheint nichts; die Notizen passen weiterhin an den eingestellten Orten."
L["MODE_TIP_MINIMAL"]      = "Nur das Nötigste zum Notieren: die Notizliste, den Editor, den Papierkorb und die Notiz-Schaltfläche in Questfenstern."
L["MODE_TIP_FULL"]         = "Alle Module eingeschaltet."
L["MODE_TIP_CUSTOM"]       = "Deine eigene Mischung: jedes Modul einzeln ein- oder ausgeschaltet."
L["CFG_MODE_CLICK_TIP"]    = "Klicken, um alle Module auf diese Zusammenstellung umzustellen."
L["CFG_MODE_CURRENT_TIP"]  = "Diese Zusammenstellung hast du gerade."
L["CFG_MODE_CUSTOM_TIP"]   = "Ausgewählt, solange deine Module keiner der Zusammenstellungen entsprechen. Stelle sie unten einzeln um."
L["CFG_MODE_CONFIRM_FMT"]  = "Auf %s umstellen? Dabei werden %d Module ein- oder ausgeschaltet. Deine Notizen und ihre Daten bleiben erhalten."
