L["CFG_PNA_LABEL"]                  = "Spielernotizen automatisch aktualisieren"
L["CFG_PNA_TIP"]                    = "An: Die Notiz eines Spielers hält sich selbst aktuell: Stufe, Gilde und Titel, wenn du ihn anvisierst, Gegenstandsstufe und Ausrüstung, wenn du ihn inspizierst, und wie oft du ihn getroffen hast. Nur der Teil über der Überschrift Notizen ändert sich; was du unter Notizen schreibst, wird nie angerührt. Eine Notiz, deren oberen Teil du von Hand änderst, aktualisiert sich nicht mehr, bis du im Inspizieren-Fenster „Ausrüstung und Notiz aktualisieren“ verwendest.\n\nAus: Spielernotizen ändern sich nur, wenn du sie selbst aktualisierst."
