L["CFG_PNA_ON_INSPECT"]             = "Sie inspiziere"
L["CFG_PNA_ON_INSPECT_TIP"]         = "An: Einen Spieler mit einer Notiz zu inspizieren zählt als Begegnung.\n\nAus: Ihn zu inspizieren aktualisiert weiterhin seine Ausrüstung, zählt aber nicht."
L["CFG_PNA_ON_GROUP"]               = "Mit ihnen gruppiere"
