L["CFG_UNIT_BADGE_TIP"]             = "Wenn der Spieler oder NPC, den du als Ziel oder Fokus hast, eine Notiz hat, sitzt ihr Symbol in der Ecke des Porträts. Klicke es an, um die Notiz zu öffnen."
L["UNIT_BADGE_TIP"]                 = "Klicken, um die Notiz zu öffnen."
L["CFG_UNIT_ENABLE_TIP"]            = "An: Notizen, die aus einem Spieler oder einem NPC entstehen: die Schaltfläche am Inspizieren-Fenster, automatische Notizen beim Inspizieren, die Notizeinträge im Rechtsklickmenü von Einheiten und die Taste für Ziel-Notizen, dazu das Live-Porträt des Ziels auf seiner Notiz, das Symbol der Notiz am Ziel- und Fokusframe und das Modell neben der Notiz.\n\nAus: Blendet alles davon aus. Deine Spieler- und NPC-Notizen bleiben als gewöhnliche Notizen in der Liste und sind wieder wie zuvor da, wenn du es erneut einschaltest."
L["CFG_RICH_ENABLE_LABEL"]          = "Rich-Notizen einschalten"
L["CFG_RICH_ENABLE_TIP"]            = "An: Notizen mit Überschriften, Farben, Symbolen, Bildern und Links: die Tabs Notiz und Markup, die Formatierungsleiste, die Live-Vorschau, In Rich-Notiz umwandeln, die Rich-Auswahl für neue Notizen und Spieler-/NPC-Notizen und die Filter für Rich und normale Notizen in der Oracle-Suche.\n\nAus: Zeigt jede Rich-Notiz als reinen Text mit sichtbarem Markup, und du kannst sie als reinen Text bearbeiten. Deine Notizen bleiben Rich: Schalte es wieder ein, sehen sie aus wie zuvor."
L["CFG_STICKY_ENABLE_TIP"]          = "An: Notizen auf deinem Bildschirm: die Haftnotiz-Schaltfläche in der Editorleiste, Als Haftnotiz öffnen im Menü der Notizliste, die Doppelklick-Auswahl, das Haftnotiz-Präfix der Oracle-Suche und Umschalt-Klick sowie Schaltfläche und Taste zum Aus-/Einblenden der Haftnotizen.\n\nAus: Schließt jede Haftnotiz und blendet alles davon aus. Notizen, die sich als Haftnotiz öffnen würden (Situationen, Alarme), erscheinen als Einblendung, und die Schnellnotiz-Taste nutzt das Hauptfenster. Die Haftnotizen, die offen waren, kommen zurück, wenn du es wieder einschaltest."
L["CFG_ALARMS_ENABLE_LABEL"]        = "Alarme einschalten"
L["CFG_ALARMS_ENABLE_TIP"]          = "An: Alarme an Notizen: das Alarmfenster in der Werkzeugleiste, die Schaltfläche in der Editorleiste, Menü und Glocke in der Notizliste, die Alarm-Schaltfläche der Haftnotizen und der Alarm-Filter der Oracle-Suche.\n\nAus: Blendet alles davon aus, und kein Alarm klingelt. Deine Alarme bleiben erhalten. Wenn du es wieder einschaltest, rücken wiederkehrende Alarme auf ihren nächsten Termin vor, und jeder andere fällige Alarm wird im Alarmfenster aufgeführt, statt zu klingeln."
L["CFG_TASKS_ENABLE_TIP"]           ="An: Aufgabenlisten an deinen Notizen: die Schaltfläche in der Editorleiste, der Aufgabenbereich, Menü und Filter der Notizliste und die Aufgabenansicht der Haftnotizen.\n\nAus: Blendet alles davon aus. Deine Aufgaben bleiben erhalten und sind wieder da, wenn du es erneut einschaltest."
L["CFG_REFBOX_MAX_TIP"]             = "Höchstzahl an Gegenständen und Zaubern, die an eine einzelne Notiz angehängt werden können (Standard: 50)."
L["CFG_SIDEBAR_ENABLE_LABEL"]       = "Charakterleiste einschalten"
L["CFG_SIDEBAR_ENABLE_TIP"]         = "Zeigt ein Symbol oder einen Tab pro Charakter neben der Notizliste, dazu Alle und Global, damit du mit einem Klick zwischen den Notizen der Charaktere wechselst."
L["CFG_SIDEBAR_AUTOSWITCH_TIP"]     = "Aktiviert beim Anmelden automatisch den Leistenplatz des Charakters, mit dem du dich anmeldest."
L["CFG_SIDEBAR_AUTOSWITCH_LABEL"]   = "Beim Anmelden automatisch zum Charakter-Tab wechseln"
L["CFG_SIDEBAR_SIDE_LABEL"]         = "Seite der Leiste"
L["CFG_SIDEBAR_SIDE_TIP"]           = "Platziert die Leiste als Tabs oben am Hauptfenster oder an seiner linken oder rechten Kante."
L["CFG_SIDEBAR_SORT_LABEL"]         = "Charaktere sortieren"
L["CFG_SIDEBAR_SORT_TIP"]           = "Die Reihenfolge der Charaktersymbole. Angeheftete Charaktere stehen immer vorn."
L["CFG_SIDEBAR_TABFILL_LABEL"]      = "Tabs füllen die Fensterbreite"
L["CFG_SIDEBAR_TABFILL_TIP"]        = "An: Die Charakter-Tabs oben am Hauptfenster teilen sich seine ganze Breite.\n\nAus: Jeder Tab behält seine eigene Breite."
L["CFG_SIDEBAR_SORT_NEWEST"]        = "Neueste zuerst"
