L["CFG_DEV_DOC_LABEL"]               = "Doku-Modus (Hilfethemen)"
L["CFG_DEV_DOC_TIP"]                 = "An: Nach einem Reload zeigt die Notizliste die Hilfethemen statt der Entwicklernotizen. Schreibe sie mit dem normalen Editor; _work/tools/docs-build.lua macht daraus den Hilfe-Ordner.\n\nAus: Wie zuvor der Entwicklernotizsatz."
L["CFG_DEV_HOLIDAY_LABEL"]          = "Weltereignis"
L["CFG_DEV_HOLIDAY_FOLLOW"]         = "Datum und Einstellung folgen"
L["CFG_DEV_HOLIDAY_NONE"]           = "Keines"
L["CFG_DEV_HOLIDAY_TIP"]            = "Zeigt das Aussehen eines Weltereignisses sofort, oder keines, unabhängig von Datum und Einstellung für Weltereignisse. Bleibt gespeichert, bis du es wieder auf Folgen stellst."
L["CFG_DEV_SNOW_PLACE"]             = "Schnee platzieren"
L["CFG_DEV_SNOW_DONE"]              = "Platzieren beenden"
L["CFG_DEV_SNOW_PLACE_TIP"]         = "Setzt auf jedes Schneestück auf dem Bildschirm ein blaues Kästchen: Ziehen verschiebt, Rechtsklick spiegelt, Mausrad ändert die Größe. Jede Änderung wird gespeichert und im Chat ausgegeben. Wähle zuerst ein Weltereignis, wenn gerade keines läuft."
L["CFG_DEV_SNOW_RESET"]             = "Schnee zurücksetzen"
L["CFG_DEV_SNOW_RESET_TIP"]         = "Vergisst jede mit „Schnee platzieren“ gesetzte Stelle."
L["CFG_DEV_SNOW_HANDLE_TIP"]        = "Ziehen: verschieben. Rechtsklick: spiegeln. Mausrad: Größe."
L["CFG_DEV_SNOW_POS_FMT"]           = "Schnee %s: x %d, y %d, Größe %.2f%s"
L["CFG_DEV_SNOW_MIRRORED"]          = ", gespiegelt"
L["CFG_DEV_DOC_RELOAD"]              = "Der Doku-Modus ändert sich beim nächsten Reload. Jetzt neu laden?"
L["CFG_DEV_MODE_COPIED_FMT"]        = "|cffff9900Entwicklermodus|r: Erster Lauf, %d Notizen in den Entwicklernotizsatz kopiert. Deine eigenen Notizen bleiben unberührt."
L["CFG_DEV_WP_LABEL"]               = "Wegpunktsystem testen"
L["CFG_DEV_WP_TIP"]                 = "Wenn eingeschaltet, werden Wegpunkt-Debuginfos in den Chat ausgegeben:"
L["CFG_DEV_TOAST_TIP_BODY"]         = "Löst CheckContextualNotes aus, als hättest du gerade deine aktuelle Zone betreten."
L["CFG_DEV_WELCOMENOTE_BTN"]        = "Willkommensnotiz auslösen"
L["CFG_DEV_WELCOMENOTE_TIP_BODY"]   = "Erzeugt die Willkommensnotiz, die eine Neuinstallation bekommt, für die Fraktion dieses Charakters (Horde, Allianz oder neutral). Jeder Klick erzeugt eine weitere, samt ihrer Einblendung."
L["CFG_DEV_UILINKS_BTN"]            = "UI-Linkliste"
L["CFG_DEV_UILINKS_TIP_BODY"]       = "Erzeugt eine Notiz (normal, mit Tag Entwurf) mit jedem BigNoteBox-Link: dem Link zum Anklicken und der Form {link*bnbui:...*}, die du in eine Rich-Notiz tippst. Ein zweiter Klick schreibt dieselbe Notiz neu, dann erscheinen neue Links."
L["CFG_DEV_PATCHNOTE_BTN"]          = "Patch-Notes auslösen"
L["CFG_DEV_PATCHNOTE_TIP_BODY"]     = "Macht, was ein Update macht: zeigt die Einblendung zu den Patch-Notes dieser Version, die sie im Ordner Patch-Notes öffnet. Eine alte angeheftete Patch-Notes-Notiz wird entfernt, außer sie wurde bearbeitet oder hat ihr Bnb-Tag verloren."
L["CFG_DEV_EXPINTRO_BTN"]          = "Release-Begrüßung"
L["CFG_DEV_EXPINTRO_TIP_BODY"]     = "Lädt neu und zeigt die Release-Begrüßung (die größten Neuerungen) über dem Hauptfenster, wie beim ersten Anmelden nach dem Update. Einblendungen warten, bis sie beantwortet ist. Die Antwort legt fest, mit welcher Ansicht sich das Fenster öffnet, wie bei einem Spieler."
L["CFG_DEV_IMM_LABEL"]              = "Position der Immersion-Schaltfläche debuggen"
L["CFG_DEV_IMM_TIP"]                = "Wenn eingeschaltet, wird der gespeicherte X/Y-Versatz bei jedem Umschalt-Ziehen und Loslassen der Schaltfläche in den Chat ausgegeben."
L["CFG_DEV_CTX_TRACE_LABEL"]        = "Situationsprüfungen verfolgen"
L["CFG_DEV_CTX_TRACE_TIP"]          = "Gibt für jede Situationsprüfung eine [ctx]-Zeile in den Chat aus (Zone, Trefferzahl, welche Notizen neu sind), für jede Haftnotiz, die sie öffnet, und jede Einblendung, die sie zeigt, dazu was 3 Sekunden später noch steht. Bleibt über Reloads an, solange der Debugmodus an ist, sodass es auch eine Anmeldung beobachten kann."
L["CFG_DEV_TOAST_ANCHOR_LABEL"]     = "Position des Einblendungsankers ausgeben"
L["CFG_DEV_ENC_GAP_LABEL"]          = "Begegnungen von Spielernotizen jede Minute"
L["CFG_DEV_ENC_GAP_TIP"]            = "An: Eine Spielernotiz zählt jede Minute eine Begegnung, ohne die Regel „einmal pro Zonenaufenthalt“, zum Testen.\n\nAus: Höchstens einmal pro Zonenaufenthalt, 30 Minuten dazwischen."
L["CFG_DEV_TOAST_ANCHOR_TIP"]       = "Gibt nach jedem Ziehen des Einblendungsankers seine gespeicherte Position (Versatz von der Bildschirmmitte) im Chat aus, samt Bildschirmgröße und UI-Skalierung."
L["CFG_TOOLBAR_DESC"]               = "Eine kleine Werkzeugleiste zwischen Zeitstempel und Notiztext. Enthält Rückgängig/Wiederholen und künftige Formatierungsschaltflächen."
L["CFG_PREVIEW_DESC"]               = "Steuerung für das Fenster der Live-Vorschau von Rich-Notizen, das das Markup in Echtzeit darstellt, während du tippst."
L["CFG_PREVIEW_DELAY_DESC"]         = "Verzögerung der Aktualisierung: wie lange nach deinem letzten Tastendruck die Vorschau neu zeichnet. Niedrigere Werte fühlen sich flotter an, können bei sehr langen Notizen aber ruckeln."
L["CFG_PREVIEW_DELAY_TIP_TITLE"]    = "Verzögerung der Vorschau-Aktualisierung"
L["CFG_PREVIEW_DELAY_TIP1"]         = "Wie lange nach deinem letzten Tastendruck die Live-Vorschau neu zeichnet."
L["CFG_PREVIEW_DELAY_TIP2"]         = "Niedriger = reaktionsschneller. Standard: 0.3 s."
L["CFG_UNDO_DESC"]                  = "Jede Notiz führt ihren eigenen Verlauf für die ganze Sitzung, auch wenn du die Notiz wechselst oder den Fokusmodus nutzt. Beim Reload oder Ausloggen wird er gelöscht, außer „Zwischen Sitzungen behalten“ unten ist an."
L["CFG_HDR_UNDO_KEEP"]              = "Zwischen Sitzungen behalten"
L["CFG_UNDO_KEEP_DESC"]             = "Normalerweise merkt sich Undo nur, was du seit dem Anmelden getippt hast: nach einem Reload oder Ausloggen startet eine Notiz ohne Undo-Schritte. Ist das hier an, werden die Undo- und Wiederholen-Schritte jeder Notiz, die du bearbeitest, beim Ausloggen oder Reload gespeichert, sodass Undo auch Änderungen aus früheren Sitzungen zurücknehmen kann.\n\nDie Schritte liegen im Addon BigNoteBox History, das mit BigNoteBox kommt, damit deine Notiz- und Einstellungsdateien klein bleiben. Eine Notiz, die die unten eingestellte Zahl von Tagen nicht bearbeitet wurde, verliert ihre gespeicherten Schritte. Wurde eine Notiz irgendwo geändert, wo Undo es nicht sehen konnte (auf einem anderen Computer oder durch einen Import), werden ihre gespeicherten Schritte verworfen, statt auf den falschen Text angewendet zu werden."
L["CFG_UNDO_KEEP_LABEL"]            = "Undo-Verlauf zwischen Sitzungen behalten"
L["CFG_UNDO_KEEP_TIP"]              = "An: Die Undo- und Wiederholen-Schritte jeder Notiz, die du bearbeitest, werden beim Ausloggen und Reload im separaten Addon BigNoteBox History gespeichert und sind wieder da, wenn du die Notiz das nächste Mal öffnest. Eine Notiz, die seither woanders geändert wurde (ein anderer Computer, ein Import), startet mit leerem Verlauf.\n\nAus: Undo und Wiederholen gelten nur für die Sitzung. Was schon gespeichert ist, bleibt, bis du es zurücksetzt."
L["CFG_UNDO_KEEP_DAYS"]             = "Aufbewahren für (Tage)"
L["CFG_UNDO_KEEP_DAYS_TIP"]         = "Der gespeicherte Verlauf einer Notiz, die so viele Tage nicht bearbeitet wurde, wird gelöscht."
L["CFG_UNDO_KEEP_SIZE_FMT"]         = "Gespeicherter Undo-Verlauf: %s, Notizen: %d"
L["CFG_UNDO_KEEP_SIZE_NONE"]        = "Gespeicherter Undo-Verlauf: keiner"
L["CFG_UNDO_KEEP_SIZE_MISSING"]     = "Das Addon BigNoteBox History fehlt oder ist in der Addon-Liste deaktiviert, deshalb wird Undo nur für die Sitzung behalten."
L["CFG_UNDO_KEEP_RESET"]            = "Undo-Verlauf löschen"
L["CFG_UNDO_KEEP_RESET_TIP"]        = "Löscht den gespeicherten Undo-Verlauf und den dieser Sitzung, für jede Notiz."
L["CFG_UNDO_KEEP_RESET_CONFIRM"]    = "Den gesamten Undo-Verlauf löschen, den gespeicherten und den dieser Sitzung, für jede Notiz?\n\nDas kann nicht rückgängig gemacht werden."
L["CFG_UNDO_KEEP_ROW_OPEN_TIP"]     = "Diese Notiz öffnen"
L["CFG_UNDO_KEEP_ROW_DEL_TIP"]      = "Den Undo-Verlauf dieser Notiz löschen"
L["CFG_UNDO_KEEP_ROW_PENDING"]      = "wird beim Reload oder Ausloggen gespeichert"
L["CFG_UNDO_KEEP_ROW_RELOAD"]       = "Jetzt neu laden"
L["CFG_UNDO_KEEP_ROW_RELOAD_TIP"]   = "Lädt die Oberfläche neu und speichert dabei den Undo-Verlauf jeder unten mit „wird beim Reload oder Ausloggen gespeichert“ markierten Notiz."
L["CFG_UNDO_DEPTH_WARN"]            = "Große Tiefe braucht mehr Speicher. Bleib bei 50 oder darunter, wenn du in derselben Sitzung viele Notizen gleichzeitig bearbeitest."
L["CFG_UNDO_DEPTH_TIP1"]            = "Wie viele Undo-Schritte pro Notiz behalten werden."
L["CFG_UNDO_DEPTH_TIP2"]            = "Standard: 50. Höhere Werte brauchen mehr Arbeitsspeicher pro Notiz."
L["CFG_AUTOSAVE_IDLE_DESC"]         = "Ruheverzögerung: wie lange nach deinem letzten Tastendruck eine Momentaufnahme gespeichert wird. Niedriger = häufigere Speicherungen."
L["CFG_AUTOSAVE_IDLE_TIP_TITLE"]    = "Ruheverzögerung"
L["CFG_AUTOSAVE_IDLE_TIP1"]         = "Wie lange nach deinem letzten Tastendruck eine Momentaufnahme gespeichert wird."
L["CFG_AUTOSAVE_IDLE_TIP2"]         = "Niedriger = häufigere Momentaufnahmen. Standard: 0.8 s."
L["CFG_AUTOSAVE_FORCED_DESC"]       = "Erzwungenes Intervall: die längste Zeit zwischen zwei Momentaufnahmen, während du ohne Pause tippst. Alle N Sekunden wird eine Momentaufnahme ausgelöst, auch wenn du nie innehältst."
L["CFG_AUTOSAVE_FORCED_TIP_TITLE"]  = "Erzwungenes Intervall"
L["CFG_AUTOSAVE_FORCED_TIP1"]       = "Die längste Zeit zwischen zwei Momentaufnahmen, während du durchgehend tippst."
L["CFG_AUTOSAVE_FORCED_TIP2"]       = "Auch wenn du nie innehältst, wird alle N Sekunden eine Momentaufnahme ausgelöst."
L["CFG_AUTOSAVE_FORCED_TIP3"]       = "Niedriger = feinere Auflösung, bis hinunter zu 0.5 s. Standard: 3 s."
L["CFG_AUTOSAVE_HIST_DESC"]         = "Automatische Momentaufnahmen werden pro Notiz bei jedem Ausloggen oder Reload gespeichert. Der Verlauf wächst nur, wenn sich Notizen ändern."
L["CFG_AUTOSAVE_SLOTS_TIP_TITLE"]   = "Automatische Momentaufnahmen pro Notiz"
L["CFG_AUTOSAVE_SLOTS_TIP1"]        = "Wie viele automatische Momentaufnahmen pro Notiz behalten werden."
L["CFG_AUTOSAVE_SLOTS_TIP2"]        = "Ältere Einträge fallen heraus, sobald die Grenze erreicht ist."
L["CFG_AUTOSAVE_SLOTS_TIP3"]        = "Standard: 5."
L["CFG_AUTOSAVE_HISTSIZE_CALC"]     = "Verlaufsgröße: wird berechnet..."
L["CFG_AUTOSAVE_HISTSIZE_FMT"]      = "Verlaufsgröße: %s, Notizen: %d"
L["CFG_UNIT_KB_FMT"]                = "%d KB"
L["CFG_EXPORT_IMG_WARN"]            = "Diese Notiz enthält Bilder. Lege deine Bilddateien in einen Ordner „img“ neben der HTML-Datei."
L["CFG_DEV_PSEUDOLOC_LABEL"]        = "Pseudo-Locale (für Übersetzer)"
L["CFG_DEV_PSEUDOLOC_TIP_BODY"]     = "Setzt vor jede Zeichenkette, die durch L[...] geht, @@.\nJeder UI-Text ohne diese Markierung ist ein fest codiertes Literal, das noch einen Sprachschlüssel braucht. Erfordert einen UI-Reload, damit schon gebaute Fenster vollständig aktualisiert werden."

