L["CFG_INTEG_ACTIVE"]                = "Aktiv"
L["CFG_INTEG_GET_BTN"]               = "Addon holen"
L["CFG_INTEG_GET_TIP"]               = "Klicken, um den CurseForge-Link zu kopieren."
L["CFG_INTEG_TOMTOM_DESC"]           = "Wegpunkte aus deinen Notizen gehen an TomTom: die Wegpunkte einer Situation, wenn du ankommst, Navigieren, /way-Links in Rich-Notizen und die Koordinaten-Schaltfläche. TomTom nimmt mehrere gleichzeitig, sein Pfeil zeigt auf den ersten, und die Wegpunkte einer Situation werden beim Verlassen wieder entfernt, wenn die Notiz das sagt."
L["CFG_INTEG_WPUI_DESC"]             = "WaypointUI zeigt die Kartennadel des Spiels in der Welt, mit Richtungspfeil und Entfernung. BigNoteBox setzt jeweils einen Wegpunkt über diese Nadel, und WaypointUI führt dich hin. Installiere zusätzlich TomTom oder MapPinEnhanced, um mehrere auf einmal zu setzen."
-- Forever / Classic: no MapPinEnhanced there (ALL-430)
L["CFG_INTEG_WPUI_DESC_TOMTOM"]      = "WaypointUI zeigt die Kartennadel des Spiels in der Welt, mit Richtungspfeil und Entfernung. BigNoteBox setzt jeweils einen Wegpunkt über diese Nadel, und WaypointUI führt dich hin. Installiere zusätzlich TomTom, um mehrere auf einmal zu setzen."
L["CFG_INTEG_MPE_DESC"]              = "Wegpunkte aus deinen Notizen gehen als benannte Nadeln in einer BigNoteBox-Gruppe an MapPinEnhanced, mehrere auf einmal. Der erste wird verfolgt, außer die Notiz sagt „Nicht verfolgen“, und die Nadeln einer Situation werden beim Verlassen wieder entfernt, wenn die Notiz das sagt."
L["CFG_INTEG_NEEDS_UPDATE"]          = "Aktualisierung nötig"
L["CFG_INTEG_DUI_DESC"]              = "Klicke in einem Quest- oder Dialoggespräch auf die Schaltfläche Text kopieren von DialogueUI, und BigNoteBox legt eine Notiz davon an: den Namen des NPC als Titel, den vollen Text als Notiz und die Belohnungen der Quest in ihrer Referenzbox. Bücher funktionieren genauso. Ein- und ausschalten unter Einstellungen > Module > Notiz-Erfassung."
L["CFG_INTEG_IMM_DESC"]              = "Während Immersion einen Quest- oder Dialogtext zeigt, schwebt eine kleine Notiz-Erfassung-Schaltfläche auf dem Bildschirm: Klicke sie, um eine Notiz des Dialogs anzulegen, Umschalt+Ziehen verschiebt sie. Ein- und ausschalten unter Einstellungen > Module > Notiz-Erfassung."
L["CFG_INTEG_MPE_UPDATE_TIP"]        ="Version 4.0 oder neuer ist nötig. Bis dahin kopiert MapPinEnhanced nur die Kartennadel des Spiels: ein Wegpunkt, ohne seinen Namen, und er bleibt, wenn du gehst."
