L["CFG_DEV_SPELLBENCH_BTN"]         = "Rechtschreib-Prüfung: Benchmark"
L["CFG_DEV_SPELLBENCH_TIP_BODY"]    = "Misst einen Text mit 5000 Wörtern und die Bearbeitungsdistanz (/bnbspell bench). Das Spiel hängt dabei etwa 9 Sekunden."
L["CFG_DEBUG_MODE_LABEL"]           = "Debugmodus (diese Sitzung)"
L["CFG_DEBUG_MODE_TIP"]             = "Schaltet die Debugbefehle ein und markiert fehlende Übersetzungen als !!KEY. Schaltet sich beim nächsten Reload oder Anmelden selbst aus. Auch /bnb debug on und /bnb debug off.\nDie Entwicklerwerkzeuge brauchen das separate Addon BigNoteBox_Dev."
L["CFG_DEBUG_MODE_DEV_TIP"]         = "Immer an, solange das Addon BigNoteBox_Dev aktiviert ist."
