L["CFG_DEVADDON_NEEDS_ADDON_TIP"]        = "Die Entwicklerwerkzeuge stecken im separaten Addon BigNoteBox_Dev, das nur für die Arbeit an BigNoteBox selbst gedacht ist. Aktiviere es in der Addon-Liste und lade neu, um sie zu nutzen."
L["CFG_DEVADDON_GET_BTN"]                = "Entwickler-Addon holen"
L["CFG_DEVADDON_GET_TIP"]                = "Warum ist Entwicklerwerkzeuge ausgegraut? Die Werkzeuge liegen im separaten Addon BigNoteBox_Dev. Klicke für einen Link auf die Seite, die erklärt, was es ist und wo du es herunterlädst. Für die Nutzung von BigNoteBox brauchst du es nicht."
L["DEV_WIN_TITLE"]                  = "Entwicklerwerkzeuge"
L["DEV_WIN_WARNING"]                = "Diese Werkzeuge sind für die Arbeit an BigNoteBox selbst, nicht für den normalen Gebrauch. Sie geben zusätzlichen Text in den Chat aus, lösen Testereignisse aus, öffnen unfertige Testfenster und können Fake-Daten anlegen. Manche wirken erst nach einem Reload vollständig.\n\nSolange BigNoteBox_Dev aktiviert ist, verwendet BigNoteBox eine eigene Kopie deiner Notizen: Notizen, die du jetzt schreibst, sind nicht in deinem eigenen Satz. Deaktiviere BigNoteBox_Dev und lade neu, um deine eigenen Notizen zurückzubekommen."
L["DEV_WIN_RELOAD_TIP"]             = "Lädt die Oberfläche neu. Manche Optionen wirken erst nach einem Reload vollständig."
L["CFG_DEV_TOAST_BTN"]              = "Test-Einblendung auslösen"
L["CFG_DEV_SETUP_BTN"]              = "Einrichtungsassistent öffnen"
