L["CFG_DEV_CTXMENU_BTN"]            = "Kontextmenü-Test"
L["CFG_DEV_CTXMENU_TIP_BODY"]       = "Öffnet am Zeiger ein Test-Rechtsklickmenü: jedes Menüsymbol, Untermenüs drei Ebenen tief, Trennlinien, eine deaktivierte Zeile und ein langes Label. Klicks werden im Chat ausgegeben."
L["CFG_DEV_FAKEADD_BTN"]             = "Fake-Daten hinzufügen"
L["CFG_DEV_FAKEADD_TIP_BODY"]        = "Nur im Entwicklermodus. Fügt 10 Fake-Charaktere hinzu, zuletzt gesehen von heute bis vor 400 Tagen, jeder mit einer bis drei eigenen Notizen (Tag fake-data). Ein erneuter Lauf ersetzt den Satz. /bnbfake"
L["CFG_DEV_FAKEDEL_BTN"]             = "Fake-Daten entfernen"
