L["CFG_CHK_RESET_WIN_SIZE_TIP"]     = "Gibt dem BigNoteBox-Fenster bei jedem Anmelden oder UI-Reload seine Standardgröße. Während des Spiels kannst du es weiterhin skalieren.\nStandardmäßig aus."
L["CFG_CHK_OPEN_CONFIG_NEW_LABEL"]  = "Notiz-Einstellungen bei neuen Notizen öffnen"
L["CFG_CHK_OPEN_CONFIG_NEW_TIP"]    = "Eingeschaltet öffnen sich die Notiz-Einstellungen neben einer gerade erstellten Notiz. Ausgeschaltet wird die neue Notiz angelegt und im Editor geöffnet, ohne sie."
L["CFG_CHK_LOCK_NOTES_LABEL"]       = "Notizen standardmäßig sperren"
L["CFG_CHK_LOCK_NOTES_TIP"]         = "Eingeschaltet öffnen sich Notizen schreibgeschützt. Klicke auf Bearbeiten, um eine Notiz zu ändern.\nEinzelne Notizen können das in den Notiz-Einstellungen überschreiben (Rechtsklick auf eine Notiz)."
L["CFG_LOCK_RESET_BTN"]             = "Alle zurücksetzen"
L["CFG_LOCK_RESET_TIP"]             = "Lässt jede Notiz wieder „Notizen standardmäßig sperren“ folgen. Notizen, die du einzeln gesperrt oder entsperrt hast, verlieren ihre eigene Einstellung und ändern sich von da an mit dieser Einstellung mit."
L["CFG_LOCK_RESET_NONE"]            = "Jede Notiz folgt bereits „Notizen standardmäßig sperren“."
