L["CFG_CHK_CONFIRM_CLOSE_LABEL"]    = "Vor dem Schließen des Notizfensters fragen"
L["CFG_CHK_CONFIRM_CLOSE_TIP"]      = "Zeigt ein Bestätigungsfenster, bevor das Hauptfenster der Notizen geschlossen wird (standardmäßig aus)."
L["CFG_CHK_TAG_TYPE_LABEL"]         = "Kreaturentyp  (z. B. Humanoider, Wildtier, Untoter)"
L["CFG_CHK_TAG_TYPE_TIP"]           = "Fügt den Typ der Kreatur als Tag hinzu (z. B. „Humanoider“, „Wildtier“, „Untoter“).\nGilt nur für Ziele, die NPCs, Gegner oder Bosse sind."
L["CFG_CHK_TAG_FAMILY_LABEL"]       = "Kreaturenfamilie  (z. B. Wolf, Spinne)"
L["CFG_CHK_TAG_FAMILY_TIP"]         = "Fügt die Familie der Kreatur als Tag hinzu (z. B. „Wolf“, „Spinne“).\nNur bei Kreaturen vom Typ Wildtier verfügbar. Standardmäßig aus."
L["CFG_CHK_TAG_CLASS_LABEL"]        = "Klassifizierung  (z. B. Elite, Selten, Weltboss)"
L["CFG_CHK_TAG_CLASS_TIP"]          = "Fügt die Klassifizierung der Kreatur als Tag hinzu (z. B. „Elite“, „Seltene Elite“, „Weltboss“).\nNormale Gegner haben keine Klassifizierung und fügen keinen Tag hinzu."
L["CFG_CHK_TAG_FACTION_LABEL"]      = "Fraktion  (z. B. Allianz, Horde)"
L["CFG_CHK_TAG_FACTION_TIP"]        = "Fügt die Fraktion des Ziels als Tag hinzu (z. B. „Allianz“, „Horde“).\nGilt für Spieler- und NPC-Ziele."
L["CFG_CHK_TAG_ZONE_LABEL"]         = "Zone  (wo die Notiz entstanden ist)"
L["CFG_CHK_TAG_ZONE_TIP"]           = "Fügt beim Anlegen der Notiz den Namen der aktuellen Zone als Tag hinzu.\nPraktisch, um festzuhalten, wo du einem Gegner oder seltenen Spawn begegnet bist."
L["CFG_CHK_TAG_BOSS_LABEL"]         = "Boss  (für Weltbosse und Ziele mit Totenkopf)"
L["CFG_CHK_TAG_BOSS_TIP"]           = "Fügt für Weltbosse und Ziele mit Totenkopf (Stufe ??) den Tag „Boss“ hinzu."
L["CFG_CHK_TASK_REMOVE_LABEL"]      = "Erledigte Aufgaben sofort entfernen"
L["CFG_CHK_TASK_REMOVE_TIP"]        = "Angehakt ist das Erledigen einer Aufgabe endgültig -- sie verschwindet sofort aus der Liste. Nicht angehakt werden erledigte Aufgaben ausgegraut und bleiben in der Liste, bis du sie von Hand leerst."
L["CFG_CHK_STICKY_TASKVIEW_LABEL"]  = "Haftnotizen standardmäßig in der Aufgabenansicht öffnen"
L["CFG_CHK_STICKY_TASKVIEW_TIP"]    = "Hat eine Haftnotiz Aufgaben, öffnet sie sich mit der Aufgabenliste. Haken entfernen, damit sie immer mit dem Notiztext öffnet."
L["CFG_CHK_ESC_DEFAULT_LABEL"]      = "Standardmäßig nur auf dem Esc-Bildschirm"
L["CFG_CHK_ESC_DEFAULT_TIP"]        = "Neue Haftnotizen erscheinen standardmäßig nur auf dem Esc-Bildschirm statt in der Spielwelt. Du kannst das auch pro Haftnotiz über ihre Einstellungen steuern (die =-Schaltfläche)."
L["CFG_CHK_ESC_DIM_LABEL"]          = "Bildschirm hinter Esc-Haftnotizen abdunkeln"
L["CFG_CHK_ESC_DIM_TIP"]            = "Zeigt eine dunkle Überlagerung hinter Haftnotizen, während das Esc-Menü offen ist, damit sie sich leichter lesen lassen. Wird automatisch abgeschaltet, wenn OneWoW aktiv ist, damit nicht doppelt abgedunkelt wird."
L["CFG_HDR_SAVING"]                 = "Speichern"
L["CFG_CHK_AUTOSAVE_LABEL"]         = "Notizen automatisch speichern"
L["CFG_CHK_AUTOSAVE_TIP"]           = "Speichert die Notiz während des Tippens, im selben Takt wie Undo (die Ruheverzögerung und das erzwungene Intervall unter Rückgängig / Wiederholen), und blendet die Speichern-Schaltfläche aus. Ausgeschaltet wird nur über die Speichern-Schaltfläche, beim Wechsel der Notiz oder beim Schließen des Fensters gespeichert. Beim Ausloggen und Reload werden Notizen in jedem Fall gespeichert."
L["CFG_CHK_STICKY_INLINE_EDIT_LABEL"] = "Haftnotiz per Doppelklick bearbeiten"
L["CFG_CHK_STICKY_INLINE_EDIT_TIP"]   = "Doppelklicke den Text einer Haftnotiz, um sie direkt dort zu bearbeiten. Escape oder ein Klick außerhalb der Notiz speichert. Formatierte (Rich-)Notizen öffnen sich stattdessen in BigNoteBox."
L["CFG_CHK_REFBOX_AUTOOPEN_LABEL"]  = "Automatisch öffnen, wenn eine Notiz mit Anhängen gewählt wird"
L["CFG_CHK_REFBOX_AUTOOPEN_TIP"]    = "Öffnet die Referenzbox, wenn du zu einer Notiz wechselst, die etwas für sie hat (Anhänge, ein Modell oder Aufgaben), und schließt sie bei einer Notiz ohne alles.\nIn der Explorer-Ansicht genügt ein Klick auf eine Notiz."
L["CFG_CHK_REFBOX_AUTOADD_LABEL"]   = "In eine Notiz gesetzte Links in ihre Referenzbox übernehmen"
L["CFG_CHK_REFBOX_AUTOADD_TIP"]     = "Ein Gegenstand, Zauber, eine Quest oder ein Haustier, den du in den Text einer Notiz ziehst oder mit Umschalt-Klick einsetzt, landet auch in der Referenzbox dieser Notiz.\nLöschst du den Link aus dem Text, bleibt er in der Referenzbox."
L["CFG_CHK_REFBOX_IDS_LABEL"]       = "Gegenstands-, Zauber- und Quest-IDs in Tooltips zeigen (BNB: <id>)"
L["CFG_CHK_REFBOX_IDS_TIP"]         = "Setzt unten in Gegenstands-, Zauber- und Quest-Tooltips eine grüne Zeile „BNB: <id>“.\nPraktisch, wenn du kein eigenes Tooltip-ID-Addon hast.\nStandardmäßig aus."
L["CFG_CHK_WYSIWYG_LABEL"]          = "Formatierungsleiste im Editor zeigen"
L["CFG_CHK_FOCUS_WYSIWYG_LABEL"]    = "Formatierungsleiste im Fokusmodus-Editor zeigen"
L["CFG_CHK_FOCUS_WYSIWYG_TIP"]      = "Die Schreibwerkzeuge der Formatierungsleiste (Rückgängig, Wiederholen, Schrift, Größe, Aufzählung, Zeitstempel) über dem Editor im Fokusmodus."
