-- BigNoteBox_History missing or disabled (ALL-466): the login popup and the
-- line on the Note History / Undo pages and their Modules rows
L["HISTORY_ADDON_NOTICE"]           = "BigNoteBox History fehlt oder ist deaktiviert.\n\nBigNoteBox bewahrt die früheren Versionen deiner Notizen (Notizverlauf) und, wenn du es willst, deine Undo-Schritte in diesem kleinen Begleit-Addon auf. Es kommt mit BigNoteBox und soll an sein.\n\nBis es in der Addon-Liste aktiviert ist, sind Notizverlauf und „Undo-Verlauf zwischen Sitzungen behalten“ aus. Deine Notizen sind nicht betroffen."
L["HISTORY_ADDON_NOTICE_NEVER"]     = "Nicht mehr zeigen"
L["CFG_HISTORY_NEEDS_ADDON"]        = "Braucht das Addon BigNoteBox History, das fehlt oder deaktiviert ist. Aktiviere es in der Addon-Liste und lade neu."
-- Rescue (ALL-466 stage 3): notes rebuilt from BigNoteBox History.
-- Settings > Modules > Note History, Settings > Backup, the History window, the login offer
L["RESCUE_HDR"]                     = "Notizen retten"
L["RESCUE_DESC"]                    = "Wenn Notizen verschwinden, ohne in BigNoteBox gelöscht worden zu sein (etwa eine beschädigte oder ersetzte Notizdatei), steht ihr Verlauf noch im Addon BigNoteBox History, und sie lassen sich hier retten. Eine gerettete Notiz kommt mit ihrem neuesten Text zurück und mit allem anderen so, wie es bei deinem letzten Ausloggen oder Reload war: Aussehen, Tags, Aufgaben, Referenzbox, Situationen, Alarm und wohin sie gehört (ihr Charakter, oder Global, wenn dieser Charakter nicht mehr in deiner Liste steht). Ein Alarm, der fällig war, während die Notiz verloren war, klingelt nicht, er wird im Alarmfenster aufgeführt. Eine Notiz, die verloren ging, bevor das hier eingeführt wurde, kommt nur mit Text, Rich-Modus, Tags und Aufgaben zurück, unter Global. Jede gerettete Notiz behält alle ihre Versionen (eine ältere lässt sich aus dem Verlauf wiederherstellen) und bekommt den Tag „Gerettet“, damit du sie finden und prüfen kannst.\n\nEine Notiz, die noch existiert, aber keinen Titel und keinen Text hat, wird ebenfalls aufgeführt: Retten setzt ihren neuesten Text wieder ein, und der leere Zustand bleibt als Version erhalten."
L["RESCUE_ALL_BTN"]                 = "Alle retten"
L["RESCUE_ALL_TIP"]                 = "Holt jede Notiz aus der Liste unten zurück, jede aus ihrer neuesten Version."
L["RESCUE_NONE"]                    = "Nichts zu retten: Jede Notiz mit Verlauf steckt in deinen Notizen."
L["RESCUE_NONE_SHORT"]              = "Gerade nichts zu retten."
L["RESCUE_COUNT_ONE"]               = "1 Notiz lässt sich retten."
L["RESCUE_COUNT_FMT"]               = "%d Notizen lassen sich retten."
L["RESCUE_ROW_BTN"]                 = "Retten"
