L["CFG_CHK_CONTEXT_SURFACE_TIP"]    = "An: Notizen mit einer Situation zeigen eine Einblendung, wenn sie passt, und setzen ihre Wegpunkte.\n\nAus: Keine Einblendungen, der Tab Situation ist verdeckt und die Marker sind ausgeblendet. Jede Notiz behält ihre Situationen und Wegpunkte, und Navigieren funktioniert weiterhin."
